// Minimal stub compatible with terminal_size 0.4.3 API
// Provides terminal_size() that queries stdout via ioctl TIOCGWINSZ.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Returns the size of the terminal, or None if not a terminal.
/// Checks stdout (fd 1). Falls back to stderr/stdin? For simplicity, check stdout only.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(libc::STDOUT_FILENO)
        .or_else(|| terminal_size_of(libc::STDERR_FILENO))
        .or_else(|| terminal_size_of(libc::STDIN_FILENO))
}

/// Returns size for specific fd.
pub fn terminal_size_of(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut winsize: libc::winsize = std::mem::zeroed();
        // TIOCGWINSZ is available via libc
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) == 0 {
            if winsize.ws_col > 0 && winsize.ws_row > 0 {
                return Some((Width(winsize.ws_col), Height(winsize.ws_row)));
            } else if winsize.ws_col > 0 {
                // Some terminals report 0 rows? Still return?
                return Some((Width(winsize.ws_col), Height(winsize.ws_row)));
            }
        }
    }
    None
}
RS
cat vendor/terminal_size/Cargo.toml
cat vendor/terminal_size/src/lib.rs
