fn auto_unit(seconds: f64) -> TimeUnit {
    if seconds < 0.001 {
        TimeUnit::Microsecond
    } else if seconds < 1.0 {
        TimeUnit::Millisecond
    } else {
        TimeUnit::Second
    }
}

fn format_time(seconds: f64, unit: TimeUnit) -> String {
    match unit {
        TimeUnit::Microsecond => {
            let v = seconds * 1e6;
            format!("{:.1} µs", v)
        }
        TimeUnit::Millisecond => {
            let v = seconds * 1e3;
            format!("{:.1} ms", v)
        }
        TimeUnit::Second => {
            format!("{:.3} s", seconds)
        }
    }
}

fn format_time_value_only(seconds: f64, unit: TimeUnit) -> String {
    // For markdown etc: just number without unit? Actually markdown shows "10.7 ± 0.1" (numbers only, unit in header). Need to format number only.
    match unit {
        TimeUnit::Microsecond => format!("{:.1}", seconds * 1e6),
        TimeUnit::Millisecond => format!("{:.1}", seconds * 1e3),
        TimeUnit::Second => format!("{:.3}", seconds),
