// Custom shell splitting for --shell=none, mimicking hyperfine's behavior (shell-words?).
// Returns Ok(tokens) or Err("missing closing quote") for unbalanced quotes.
// Handles:
// - Whitespace splitting (space, tab, newline) – splits, collapses.
// - Single quotes: '...' – content literal, no escapes except ' to end? Inside single, no backslash escapes? In POSIX, inside single quotes, backslash is literal, only ' ends. Good. Unbalanced single => error.
// - Double quotes: "..." – inside, backslash escapes $,`,",\,newline? Actually in POSIX double quotes, backslash escapes $,`,",\,newline, else literal? And ", $ etc.? For splitting (not expansion), $ and ` are literal? Since hyperfine does not expand variables (echo $HOME with shell=none gives $HOME literal, not expanded). Good. So inside double, treat $,` as literal, only handle \" and \\ and \newline? Actually original: echo "a  b" with shell=none gave "a  b" (with double spaces preserved, quotes removed). Good. What about echo "a\"b" (escaped quote inside double)? Should give a"b? Let's assume POSIX double quote rules: \ escapes $,`,",\,newline; else \ literal.
// - Backslash outside quotes: \ escapes next char (including space, #, quotes, backslash, etc.)? For "echo a\\ b" (a, backslash, space, b)? Actually "echo a\\ b" in our test "echo a\\b" (a, \\, b) gave "a\\b"? Wait "echo a\\\\b" (a, \\, b) in shell=none gave "a\\b" (a, \, b)? Hmm. Let's implement standard: \ + any char => that char literal (removing \)? Except \ + newline => line continuation (remove both)? For trailing \ with no following char (end of input): treat as literal "\" (not error), to match original's allowing trailing \. Good.
// - # comments: # starts comment when at beginning of word? Actually when # is first char of a token (after whitespace) and not inside quotes? And rest of line ignored? For "echo hi # comment", tokens ["echo","hi"] (comment stripped). For "echo a#b" (no space before #), tokens ["echo","a#b"] (# not comment). Good. Implement: When encountering # at start of word (i.e., after whitespace, beginning of token, not inside quotes, and not escaped), skip rest of input (until newline? Since input is single line (command string may contain newline? Command string could contain newline? E.g., 'echo hi\n echo ho' with actual newline? Unlikely, but handle: skip until newline or end). Good.
// - Empty input or only whitespace/comments => Ok([]) (empty tokens) => caller gives "Can not execute empty command".
// - Unbalanced quotes => Err("missing closing quote").
fn shell_split(s: &str) -> Result<Vec<String>, String> {
    let bytes = s.as_bytes();
    let n = bytes.len();
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut in_token = false; // whether currently building a token (to handle empty quoted strings? e.g., 'echo ""' should give ["echo",""] (second token empty string)? Does hyperfine handle empty quoted? Test with 'echo ""' and shell=none: should output empty line (echo with empty arg)? Let's assume yes. Our in_token logic must handle: When we encounter quotes (even empty), we start a token (in_token=true), even if cur remains empty. Good.
    let mut i = 0usize;
    while i < n {
        let c = bytes[i] as char;
        // Handle whitespace outside quotes? We are not inside quotes here (quotes handled inside branches that consume until closing). So here, c is outside quotes.
        if c == ' ' || c == '\t' || c == '\n' {
            // End of token? If in_token, push cur (even if empty? Actually if cur empty and in_token true due to previous quotes, push empty? Example: 'echo ""' -> after echo, space, then "" (quoted empty) -> cur empty but in_token true, push "".
            if in_token {
                tokens.push(cur.clone());
                cur.clear();
                in_token = false;
            }
            // Skip whitespace
            i += 1;
            while i < n && (bytes[i] == b' ' || bytes[i] == b'\t' || bytes[i] == b'\n') {
                i += 1;
            }
            continue;
        } else if c == '#' && !in_token {
            // Start of comment? Only if at beginning of token (i.e., not in_token, meaning after whitespace or at start). Actually need to check: # starts comment when it's first char of a word (i.e., after whitespace)? Our in_token is false after whitespace, so # here is at start. Good. Skip rest.
            // Skip until newline or end (since command string may contain newline? If newline, break? Actually newline ends comment and also is whitespace? For simplicity, skip until end (since hyperfine commands are single line? But could contain newline via actual newline char in arg? Unlikely. Skip to end.
            break;
        } else if c == '\'' {
            // Single quote: consume until closing ', no escapes.
            in_token = true;
            i += 1;
            let mut closed = false;
            while i < n {
                let cc = bytes[i] as char;
                if cc == '\'' {
                    closed = true;
                    i += 1;
                    break;
                } else {
                    cur.push(cc);
                    i += 1;
                }
            }
            if !closed {
                return Err("missing closing quote".to_string());
            }
            // Continue (still in_token, may have more chars in same token, e.g., 'a'b'c' => abc? In shell, 'a'b'c' (single quoted a, then b, then single quoted c) concatenates to abc in same token (no spaces). Good. Our loop continues without pushing, still in_token. Good.
        } else if c == '"' {
            // Double quote: consume until closing ", handling backslashes.
            in_token = true;
            i += 1;
            let mut closed = false;
            while i < n {
                let cc = bytes[i];
                if cc == b'"' {
                    closed = true;
                    i += 1;
                    break;
                } else if cc == b'\\' {
                    // Backslash inside double: check next char
                    if i + 1 >= n {
                        // Trailing backslash inside double with no following char (end of input before closing ")? Then missing closing quote? Actually input ends with \" (backslash then end, no closing ")? Example: 'echo "hi\\' (double quote, hi, backslash, end, no closing)? That's unbalanced (missing closing) + trailing backslash. Should error missing closing? Likely. Return error.
                        return Err("missing closing quote".to_string());
                    }
                    let nxt = bytes[i+1];
                    match nxt as char {
                        '$' | '`' | '"' | '\\' => {
                            cur.push(nxt as char);
                            i += 2;
                        },
                        '\n' => {
                            // \<newline> => line continuation, remove both (no char)
                            i += 2;
                        },
                        _ => {
                            // \x (x not special) => keep both? In POSIX double quotes, \x where x not special => \ and x both literal? Actually "\a" => "\a" (backslash + a)? Or "a"? In POSIX, inside double quotes, backslash retains special meaning only when followed by $,`,",\,newline. Otherwise, backslash is literal? So "\a" => "\a" (two chars). Good. So push "\" and "a".
                            cur.push('\\');
                            cur.push(nxt as char);
                            i += 2;
                        }
                    }
                } else {
                    cur.push(cc as char);
                    i += 1;
                }
            }
            if !closed {
                return Err("missing closing quote".to_string());
            }
        } else if c == '\\' {
            // Backslash outside quotes: escape next char, or trailing?
            in_token = true;
            if i + 1 >= n {
                // Trailing backslash at end of input (no following char): treat as literal "\" (to match original allowing trailing \). Good.
                cur.push('\\');
                i += 1;
            } else {
                let nxt = bytes[i+1];
                if nxt == b'\n' {
                    // \<newline> => line continuation, remove both (no char), and also? Still in_token? Yes.
                    i += 2;
                } else {
                    // \<any> => literal <any> (remove backslash)? For "\ " (escaped space) => space literal, not splitting. Good. For "\\" (escaped backslash) => "\" literal. Good. For "\#" => "#" literal (not comment). Good.
                    cur.push(nxt as char);
                    i += 2;
                }
            }
        } else {
            // Regular char (including '#'? # inside token (not at start) is literal, not comment. Good. Since we only treat # as comment when !in_token (at start), here in_token may be true or false? If !in_token and c=='#', we handled above as comment (break). Here, if !in_token and c!='#', it's start of new token with regular char. Good. If in_token, continue token.
            // If c=='#' and in_token true, it's literal (not comment). Good. So this branch handles it (since previous # check only when !in_token).
            in_token = true;
            cur.push(c);
            i += 1;
        }
    }
    if in_token {
        tokens.push(cur);
    }
    Ok(tokens)
}

